def round_outcome(scores_dict, response=''):
    if scores_dict is None:
        return None
    from vdriftbench.judge import detect_non_delivery
    if 'non_delivery' in scores_dict:
        nd = bool(scores_dict['non_delivery'])
    else:
        nd = detect_non_delivery(response) is not None
    js = JudgeScores(
        VDS=scores_dict['VDS'], EFS=scores_dict['EFS'], NJS=scores_dict['NJS'],
        SCS=scores_dict['SCS'], IFR=scores_dict['IFR'],
        raw_rationale=scores_dict.get('raw_rationale',''),
        non_delivery=nd,
    )
    return js.outcome(mode=OUTCOME_MODE_BINARY)

def v314_r5_success(result):
