    # fallback: any round success
    for rd in row.get('rounds', []):
        if round_outcome(rd.get('scores'), rd.get('target_response','')) == '成功':
            return True
    return False

pair_succ = {sid for sid, row in pair_rows.items() if pair_success(row)}
v314_r5_fail = {sid for sid, r in v314.items() if not v314_r5_success(r)}
