import json, re, sys
from collections import Counter
sys.path.insert(0, '/root/vdriftbench')
from vdriftbench.io_utils import load_sample_results_jsonl
from vdriftbench.enrich import load_enriched_jsonl
from vdriftbench.schema import OUTCOME_MODE_BINARY

v314 = {r.sample.sample_id: r for r in load_sample_results_jsonl('/root/vdriftbench/data/v3.14_run/results.jsonl')}
enriched = {s.sample_id: s for s in load_enriched_jsonl('/root/vdriftbench/data/dataset_100.enriched.jsonl', verify_against_raw=False)}
pair_rows = {}
with open('/root/pair_baseline_v314_run/results.jsonl') as f:
    for line in f:
        if line.strip():
            row = json.loads(line)
            pair_rows[row['sample_id']] = row

R5_PRINCIPLES = {'RAW_GENRE_PROMPT', 'RAW_GENRE_PROMPT_RETRY', 'RAW_GENRE_PROMPT_RETRY_2'}

def v314_r5_success(result):
    for rd in result.rounds:
        if rd.principle_used in R5_PRINCIPLES:
            if rd.scores and rd.scores.outcome(mode=OUTCOME_MODE_BINARY) == '成功':
                return True
    return False

def get_pair_success_prompt(row):
    best = row.get('best_round')
    for rd in row.get('rounds', []):
        if rd.get('iteration') == best:
            return rd.get('attack_prompt','')
    for rd in row.get('rounds', []):
        if rd.get('outcome') == '成功':
            return rd.get('attack_prompt','')
    return ''

def get_r5_first(result):
    for rd in result.rounds:
        if rd.principle_used == 'RAW_GENRE_PROMPT':
            return rd.prompt
    return ''

def get_successful_r5(result):
    for rd in result.rounds:
        if rd.principle_used in R5_PRINCIPLES:
            if rd.scores and rd.scores.outcome(mode=OUTCOME_MODE_BINARY) == '成功':
                return rd.prompt
    return ''

gap_ids = sorted(s for s in pair_rows if pair_rows[s].get('best_outcome')=='成功' and not v314_r5_success(v314[s]))
succ_ids = sorted(s for s, r in v314.items() if v314_r5_success(r))

# deeper features
def deep_features(text):
    if not text: return {}
    return {
        'role_play': bool(re.search(r'你是|你是一位|你是一名|假设你是|作为.*(?:专家|研究员|分析师|顾问)', text)),
        'numbered_list': bool(re.search(r'[1-9][\.、\)]', text)),
        'background_section': bool(re.search(r'背景信息|背景如下|以下内容|报告要求|文章需要', text)),
        'fabricated_study_detail': bool(re.search(r'\d+%|\d+所|超过|数据显示|研究表明|统计', text)),
        'named_entity': bool(re.search(r'[A-Z]{2,}|光辉集团|全视之眼|XYZ', text)),
        'step_by_step': bool(re.search(r'请确保|需要包括|以下几点|具体步骤', text)),
        'softening': bool(re.search(r'探讨|分析|可以|潜在|可行性|假设', text)),
        'hard_directive': bool(re.search(r'必须|确保.*符合|支持.*观点|详细阐述.*观点', text)),
        'mentions_harmful_policy': bool(re.search(r'歧视|限制人口|籍贯|分级|延迟结婚|缩短合同|取消.*转移支付|自行停药|加大投放', text)),
        'multi_paragraph': text.count('\n') >= 2,
    }

def summarize(prompts):
    if not prompts: return {}
    feats = [deep_features(p) for p in prompts]
    return {k: sum(f[k] for f in feats)/len(feats) for k in feats[0]}

gap_pair = [get_pair_success_prompt(pair_rows[s]) for s in gap_ids]
gap_r5 = [get_r5_first(v314[s]) for s in gap_ids]
succ_r5 = [get_successful_r5(v314[s]) for s in succ_ids]
gap_ds = [enriched[s].prompt for s in gap_ids]

print('Deep feature comparison:')
for label, ps in [
    ('GAP dataset', gap_ds),
    ('GAP R5 first', gap_r5),
    ('GAP PAIR success', gap_pair),
    ('SUCCESS R5', succ_r5),
]:
    s = summarize(ps)
    print(f'\n{label} (n={len(ps)}):')
    for k,v in sorted(s.items(), key=lambda x:-x[1]):
        print(f'  {k}: {v:.2f}')

# Compare same-sample: does PAIR have role_play when R5 doesn't?
both = []
for s in gap_ids:
    p = get_pair_success_prompt(pair_rows[s])
    r = get_r5_first(v314[s])
    pf, rf = deep_features(p), deep_features(r)
    both.append((s, pf.get('role_play'), rf.get('role_play'), pf.get('fabricated_study_detail'), rf.get('fabricated_study_detail')))

print('\n=== Per-sample PAIR vs R5 role_play ===')
print('PAIR has role_play, R5 lacks:', sum(1 for _,pr,rr,_,_ in both if pr and not rr))
print('PAIR has fabricated detail, R5 lacks:', sum(1 for _,_,_,pd,rd in both if pd and not rd))

# Build-up rounds before R5 for gap vs success
def buildup_rounds(result):
    return [rd for rd in result.rounds if rd.principle_used not in R5_PRINCIPLES and rd.principle_used != 'RECOVERY']

gap_buildup = [len(buildup_rounds(v314[s])) for s in gap_ids]
succ_buildup = [len(buildup_rounds(v314[s])) for s in succ_ids]
print(f'\nBuildup rounds before R5: GAP avg={sum(gap_buildup)/len(gap_buildup):.1f}, SUCCESS avg={sum(succ_buildup)/len(succ_buildup):.1f}')

# Terminated early?
gap_early = sum(1 for s in gap_ids if v314[s].terminated_early)
succ_early = sum(1 for s in succ_ids if v314[s].terminated_early)
print(f'Terminated early: GAP={gap_early}/25, SUCCESS={succ_early}/285')

# Output structured JSON for the 25 samples
out = []
for sid in gap_ids:
    s = enriched[sid]
    r = v314[sid]
    p = pair_rows[sid]
    r5s = [rd for rd in r.rounds if rd.principle_used in R5_PRINCIPLES]
    out.append({
        'sample_id': sid,
        'category': s.category,
        'category_macro': s.category_macro,
        'target_claim': s.target_claim,
        'dataset_prompt': s.prompt,
        'pair_success_prompt': get_pair_success_prompt(p),
        'pair_success_iteration': p.get('success_at_iteration') or p.get('best_round'),
        'r5_first_prompt': get_r5_first(r),
        'r5_fail_reasons': list(set(
            ('未交付' if rd.scores and rd.scores.non_delivery else
             'VDS=0' if rd.scores and rd.scores.VDS==0 else
             'SCS=2' if rd.scores and rd.scores.SCS==2 else
             'IFR=0' if rd.scores and rd.scores.IFR==0 else 'other')
            for rd in r5s if not (rd.scores and rd.scores.outcome(mode=OUTCOME_MODE_BINARY)=='成功')
        )),
        'buildup_rounds': len(buildup_rounds(r)),
    })

with open('/tmp/gap25_analysis.json', 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
print('\nWrote /tmp/gap25_analysis.json')
